<template>
 <div class="song-navigator" role="group" :aria-label="$t('Song Navigator')">
  <header><strong>{{ $t('Song Navigator') }}</strong><span>{{ Math.ceil(total/192) }} {{ $t('compases') }} · {{ $t('Vista') }} {{ (start/192+1).toFixed(1) }}–{{ ((start+span)/192+1).toFixed(1) }}</span></header>
  <svg ref="map" viewBox="0 0 1000 76" preserveAspectRatio="none" role="slider" tabindex="0" :aria-label="$t('Navegar por la canción')" :aria-valuemin="0" :aria-valuemax="Math.max(0,total-span)" :aria-valuenow="start" @pointerdown="begin" @pointermove="move" @pointerup="finish" @pointercancel="cancel" @lostpointercapture="cancel" @keydown.left.stop.prevent="navigate(start-span/4)" @keydown.right.stop.prevent="navigate(start+span/4)">
   <g v-for="t in tracks" :key="t.channel" :style="{color:colors[t.channel%colors.length]}"><rect v-for="r in t.regions" :key="r.id" :x="r.start/total*1000" :y="5+t.channel*8" :width="Math.max(2,(r.end-r.start)/total*1000)" height="6" fill="currentColor" opacity=".75" /></g>
   <rect :x="start/total*1000" y="1" :width="Math.min(1000,span/total*1000)" height="74" class="navigator-window" /><line :x1="cursor/total*1000" y1="0" :x2="cursor/total*1000" y2="76" class="edit-cursor" pointer-events="none" /><line :x1="cursor/total*1000" y1="0" :x2="cursor/total*1000" y2="76" stroke="transparent" stroke-width="14" vector-effect="non-scaling-stroke" pointer-events="stroke" class="cursor-hit" @pointerdown.stop="beginCursor" />
  </svg>
 </div>
</template>
<script>
import {clamp,timelineTime} from '../editor/timeline.mjs';
export default {props:{tracks:Array,total:Number,start:Number,span:Number,cursor:Number,colors:Array},emits:['navigate','seek','scrub-start','scrub-end'],data(){return {drag:null};},methods:{navigate(tick){this.$emit('navigate',clamp(tick,0,Math.max(0,this.total-this.span)));},at(e){const b=this.$refs.map.getBoundingClientRect();return timelineTime((e.clientX-b.left)/b.width,0,this.total);},begin(e){if(e.button!==0)return;e.preventDefault();e.currentTarget.setPointerCapture(e.pointerId);const tick=this.at(e),inside=tick>=this.start&&tick<=this.start+this.span;this.drag={offset:inside?tick-this.start:this.span/2};this.navigate(tick-this.drag.offset);},beginCursor(e){if(e.button!==0)return;e.preventDefault();this.$refs.map.setPointerCapture(e.pointerId);this.drag={cursor:true};this.$emit('scrub-start');this.$emit('seek',this.at(e));},move(e){if(!this.drag)return;if(this.drag.cursor)this.$emit('seek',this.at(e));else this.navigate(this.at(e)-this.drag.offset);},finish(e){if(this.drag?.cursor)this.$emit('seek',this.at(e));this.cancel();},cancel(){const cursor=this.drag?.cursor;this.drag=null;if(cursor)this.$emit('scrub-end');}}};
</script>
<style scoped>
.song-navigator{position:sticky;top:0;z-index:5;padding:10px 14px;background:#19222e;border-bottom:1px solid #354153;border-radius:10px 10px 0 0}.song-navigator header{display:flex;justify-content:space-between;gap:12px;margin-bottom:7px;font-size:11px;color:#aab9cc}.song-navigator strong{color:#dce8f6;text-transform:uppercase;letter-spacing:.12em}.song-navigator svg{width:100%;height:64px;background:#101720;border-radius:4px;display:block;cursor:grab;touch-action:none}.navigator-window{fill:#b9d2ff14;stroke:#c4d5eb;stroke-width:2;vector-effect:non-scaling-stroke}.edit-cursor{stroke:#f2c065;stroke-width:2;vector-effect:non-scaling-stroke}.cursor-hit{cursor:ew-resize}svg:focus-visible{outline:2px solid #77c7ff}
</style>
